// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am) public {
        vm.assume(_val > 0);
        vm.assume(_am <= _val);
        vm.assume(_lockTime <= 100000000);

        // The buggy contract allows SetMinSum to be called even after initialization.
        // In the reference, SetMinSum must be called before Initialized() to set MinSum.
        // We attempt to set MinSum, then initialize, then update balances and collect.
        c.SetMinSum(_val);
        c.Initialized();

        // Provide funds to the test caller
        address caller = address(this);
        vm.deal(caller, _val);

        // Put funds with lock time
        c.Put{value: _val}(_lockTime);

        // Warp to after unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // Collect
        c.Collect(_am);

        // In the reference (correct contract), after initialization,
        // SetMinSum cannot be called, so MinSum remains 0 because
        // Initialized() was called before any SetMinSum?
        // Actually in this order, SetMinSum succeeds before Initialized.
        // To distinguish, we need a different approach:
        // The bug allows SetMinSum after Initialized.
        // So we should test that in the reference, MinSum cannot be changed
        // after Initialized, whereas in buggy it can.

        // Reset the test: do SetMinSum after Initialized
        c = new C();
        c.Initialized();
        c.SetMinSum(_val);

        // In reference, this SetMinSum should revert (due to if(intitalized)revert();)
        // In buggy, it should succeed and set MinSum to _val.
        // So property: after Initialized, calling SetMinSum should leave MinSum unchanged (still 0).
        assertTrue(c.MinSum() == 0, "MinSum should be 0 after initialization if SetMinSum reverted");
    }
}

