pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 setVal, uint256 lockTime, uint256 collectAmt, uint256 depositAmt) public {
        // Bound inputs to avoid overflow and ensure meaningful tests
        setVal = bound(setVal, 0, 1e18);
        lockTime = bound(lockTime, 0, 1e6);
        collectAmt = bound(collectAmt, 0, 1e18);
        depositAmt = bound(depositAmt, 0, 1e18);

        // Initialize the contract
        c.Initialized();

        // Optionally set MinSum
        bool setMinSumCalled = setVal > 0;
        if (setMinSumCalled) {
            c.SetMinSum(setVal);
        }

        // Deposit value into the contract via Put
        vm.deal(address(this), depositAmt);
        (bool successPut, ) = address(c).call{value: depositAmt}(abi.encodeWithSignature("Put(uint256)", lockTime));
        if (!successPut) return; // skip if Put fails

        // Attempt Collect
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        if (!successCollect) return; // only check assertion on successful Collect

        // Read MinSum after Collect
        uint256 minSumAfter = c.MinSum();

        // Assert: MinSum equals the last value set by SetMinSum, or 0 if never set
        if (setMinSumCalled) {
            assertTrue(minSumAfter == setVal, "MinSum should equal the value set by SetMinSum");
        } else {
            assertTrue(minSumAfter == 0, "MinSum should remain 0 if SetMinSum was never called");
        }
    }
}

