pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint setVal, uint collectAmt, uint lockTime, bool callSetMin, bool callInitFirst) public {
        // Bound inputs to reasonable ranges
        setVal = bound(setVal, 0, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);
        lockTime = bound(lockTime, 0, 1000000);

        // Sequence: optionally set, optionally initialize, then Collect
        uint expectedMinSum = 0;
        if (callSetMin) {
            c.SetMinSum(setVal);
            expectedMinSum = setVal;
        }
        if (callInitFirst) {
            c.Initialized();
        }

        // Prepare a sender with balance for Collect
        address sender = address(0x1234);
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put(lockTime);

        // Advance time so Collect can succeed (if Put set unlockTime)
        vm.warp(block.timestamp + lockTime + 1);

        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // Rule: MinSum must equal the value set by the last SetMinSum before Initialized (or 0 if never set)
        // If Initialized was called before SetMinSum, SetMinSum reverts, so MinSum stays as before.
        if (callInitFirst && callSetMin) {
            // SetMinSum would revert because initialized, so expected stays previous (0 if no prior SetMinSum, or setVal if prior)
            // Since we have no prior, expected remains 0
            assertTrue(c.MinSum() == 0);
        } else {
            assertTrue(c.MinSum() == expectedMinSum);
        }
    }
}

