pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 depositAmount, uint256 collectAmount, bool callSetMinSumBeforeInit, bool callSetMinSumAfterInit) public {
        // Precondition: restrict to avoid overflow and ensure meaningful test
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(lockTime <= type(uint256).max / 2);
        vm.assume(depositAmount > 0 && depositAmount <= address(c).balance + 1e18); // ensure sender has enough
        vm.assume(collectAmount <= depositAmount);

        // Prepare user
        address user = address(0x1234);
        vm.deal(user, depositAmount);
        vm.prank(user);

        // Optionally set MinSum before initialization
        if (callSetMinSumBeforeInit) {
            c.SetMinSum(minSum);
        }

        // Initialize
        c.Initialized();

        // Optionally call SetMinSum after initialization (will revert due to intitalized check)
        if (callSetMinSumAfterInit) {
            // This call will revert, but we catch it to continue
            (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", minSum + 1));
            vm.assume(!success); // ensure it reverts as expected
        }

        // Record MinSum before Put
        uint256 minSumBefore = c.MinSum();

        // Put deposit
        vm.prank(user);
        c.Put{value: depositAmount}(lockTime);

        // Try Collect (may revert, that's fine)
        vm.prank(user);
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record MinSum after Collect
        uint256 minSumAfter = c.MinSum();

        // Assert: MinSum does not change as a result of the Collect call
        assertTrue(minSumBefore == minSumAfter, "MinSum changed after Collect");
    }
}

