pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 funds, uint256 lockTime, uint256 minSum, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        vm.deal(caller, funds);
        uint256 initBal = address(caller).balance;

        vm.prank(caller);
        c.SetMinSum(minSum);
        vm.prank(caller);
        c.Initialized();

        vm.prank(caller);
        c.Put{value: funds}(lockTime);

        // Ensure Collect will succeed: balance >= minSum, balance >= collectAmt, time > unlockTime
        vm.warp(block.timestamp + lockTime + 1);
        vm.assume(funds >= minSum && funds >= collectAmt);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // If Collect succeeded, caller's balance should have increased by collectAmt (since it's received via call)
        uint256 finalBal = address(caller).balance;
        assertTrue(ok && finalBal == initBal + collectAmt);
    }
}

