pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 lockTime, uint256 minSum) public {
        // Bound inputs to reasonable ranges
        amount = bound(amount, 0, 100 ether);
        lockTime = bound(lockTime, 0, 365 days);
        minSum = bound(minSum, 0, 100 ether);

        // Set up the contract
        vm.prank(address(0xdead));
        c.SetMinSum(minSum);

        // Deploy a mock Log contract and set it
        Log logAddr = new Log();
        c.SetLogFile(address(logAddr));

        // Initialize
        vm.prank(address(0xdead));
        c.Initialized();

        // Put some ether into the contract
        vm.deal(address(this), amount);
        c.Put{value: amount}(lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Record the log count before Collect
        uint256 logCountBefore = logAddr.History.length();

        // Try to collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        // Read log count after
        uint256 logCountAfter = logAddr.History.length();

        // The rule: if Collect succeeded, log count should increase by exactly 1
        // In reference, SetLogFile sets the log, so the call succeeds and adds one log
        // In mutant, SetLogFile does nothing, so the call reverts (no log address), and log count stays same
        if (success) {
            assertTrue(logCountAfter == logCountBefore + 1, "Log count should increase by 1 on successful Collect");
        } else {
            assertTrue(logCountAfter == logCountBefore, "Log count should stay same on failed Collect");
        }
    }
}

