pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _am, uint _lockTime, uint _initialDeposit) public {
        // Bound inputs to reasonable ranges
        _am = bound(_am, 0.001 ether, 100 ether);
        _lockTime = bound(_lockTime, 0, 365 days);
        _initialDeposit = bound(_initialDeposit, _am, 200 ether);

        // Setup: set MinSum to 0, initialize, and fund the contract
        c.SetMinSum(0);
        vm.deal(address(this), _initialDeposit);
        c.Put{value: _initialDeposit}(_lockTime);
        c.Initialized();

        // Advance time past unlock
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));

        if (success) {
            // Read the last log entry from Log contract (we need to get the Log address via public getter)
            address logAddr = address(c.LogFile());
            // The Log contract has a public History array; read the last entry
            // First get the length
            (bool ok, bytes memory lenData) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", 0));
            assertTrue(ok);
            // Decode the first entry (we only pushed one message during Collect)
            // Actually we need the last entry; but since only one Collect message was added, index 0 is fine
            (bool ok2, bytes memory msgData) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", 0));
            assertTrue(ok2);
            // Decode the tuple (address, string, uint256, uint256)
            (address _sender, string memory _data, uint256 _val, uint256 _time) = abi.decode(msgData, (address, string, uint256, uint256));
            // The logged value should equal _am
            assertTrue(_val == _am);
        } else {
            // If it reverts, there's no log entry, but we don't care
            assertTrue(true);
        }
    }
}

